CREATE TABLE public.audit_logs (
    id uuid DEFAULT app.uuidv7() NOT NULL,
    actor_user_id uuid,
    actor_role_code text,
    actor_type text NOT NULL,
    action text NOT NULL,
    subject_type public.subject_type,
    subject_id uuid,
    before_state jsonb,
    after_state jsonb,
    request_id text,
    ip_address inet,
    user_agent text,
    amount_kobo bigint,
    occurred_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT audit_logs_actor_type_check CHECK ((actor_type = ANY (ARRAY['user'::text, 'system'::text, 'service'::text, 'webhook'::text]))),
    CONSTRAINT audit_logs_amount_kobo_check CHECK (((amount_kobo IS NULL) OR (amount_kobo >= 0))),
    CONSTRAINT audit_logs_has_payload CHECK (((before_state IS NOT NULL) OR (after_state IS NOT NULL) OR (action ~~ '%.read'::text)))
);

ALTER TABLE ONLY public.audit_logs FORCE ROW LEVEL SECURITY;


--

--

COMMENT ON TABLE public.audit_logs IS 'Append-only, and the answer to most support questions. actor_role_code is the role held at the time of the action, not the role held now, because a role change must not retroactively change what somebody was permitted to do.';


