CREATE TABLE public.disputes (
    id uuid DEFAULT app.uuidv7() NOT NULL,
    ajo_id uuid NOT NULL,
    round_id uuid,
    contribution_id uuid,
    payout_id uuid,
    raised_by_user_id uuid NOT NULL,
    against_user_id uuid,
    reason_id uuid NOT NULL,
    category text NOT NULL,
    status public.dispute_status DEFAULT 'open'::public.dispute_status NOT NULL,
    description text NOT NULL,
    resolution text,
    resolved_at timestamp with time zone,
    resolved_by_user_id uuid,
    is_private boolean DEFAULT true NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    deleted_at timestamp with time zone,
    version integer DEFAULT 1 NOT NULL,
    CONSTRAINT disputes_not_self_dispute CHECK (((against_user_id IS NULL) OR (against_user_id <> raised_by_user_id))),
    CONSTRAINT disputes_open_has_no_resolution CHECK (((status = ANY (ARRAY['resolved'::public.dispute_status, 'withdrawn'::public.dispute_status])) OR (resolution IS NULL))),
    CONSTRAINT disputes_resolved_consistent CHECK (((status <> ALL (ARRAY['resolved'::public.dispute_status, 'withdrawn'::public.dispute_status])) OR (resolved_at IS NOT NULL)))
);

ALTER TABLE ONLY public.disputes FORCE ROW LEVEL SECURITY;


