CREATE TABLE public.reconciliation_runs (
    id uuid DEFAULT app.uuidv7() NOT NULL,
    run_type text NOT NULL,
    window_start timestamp with time zone NOT NULL,
    window_end timestamp with time zone NOT NULL,
    status public.reconciliation_status DEFAULT 'running'::public.reconciliation_status NOT NULL,
    expected_kobo bigint DEFAULT 0 NOT NULL,
    actual_kobo bigint DEFAULT 0 NOT NULL,
    variance_kobo bigint DEFAULT 0 NOT NULL,
    findings jsonb DEFAULT '{}'::jsonb NOT NULL,
    blocks_disbursement boolean DEFAULT true NOT NULL,
    triggered_by_user_id uuid,
    notes text,
    started_at timestamp with time zone DEFAULT now() NOT NULL,
    finished_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    deleted_at timestamp with time zone,
    version integer DEFAULT 1 NOT NULL,
    CONSTRAINT reconciliation_runs_actual_kobo_check CHECK ((actual_kobo >= 0)),
    CONSTRAINT reconciliation_runs_expected_kobo_check CHECK ((expected_kobo >= 0)),
    CONSTRAINT reconciliation_runs_finished_has_timestamp CHECK (((status = 'running'::public.reconciliation_status) OR (finished_at IS NOT NULL))),
    CONSTRAINT reconciliation_runs_run_type_check CHECK ((run_type = ANY (ARRAY['daily'::text, 'on_demand'::text, 'post_incident'::text, 'pre_disbursement'::text]))),
    CONSTRAINT reconciliation_runs_variance_is_consistent CHECK ((variance_kobo = (expected_kobo - actual_kobo))),
    CONSTRAINT reconciliation_runs_window_ordered CHECK ((window_end > window_start))
);


--

--

COMMENT ON TABLE public.reconciliation_runs IS 'A proof, over a window, that the internal ledger agrees with the provider and with the round expectations. This is the artefact a regulator or an auditor asks for, so it references a time window rather than the rows it checks: the proof must outlive the things it proves.';


