CREATE TABLE public.risk_events (
    id uuid DEFAULT app.uuidv7() NOT NULL,
    subject_type public.risk_subject_type NOT NULL,
    subject_id uuid NOT NULL,
    event_type text NOT NULL,
    severity public.risk_severity DEFAULT 'low'::public.risk_severity NOT NULL,
    status public.risk_event_status DEFAULT 'open'::public.risk_event_status NOT NULL,
    score smallint DEFAULT 0 NOT NULL,
    signals jsonb DEFAULT '{}'::jsonb NOT NULL,
    decision public.risk_decision,
    decision_note text,
    decided_by_user_id uuid,
    decided_at timestamp with time zone,
    assigned_to_user_id uuid,
    expires_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    deleted_at timestamp with time zone,
    version integer DEFAULT 1 NOT NULL,
    CONSTRAINT risk_events_decided_by_required CHECK (((decision IS NULL) OR (decided_by_user_id IS NOT NULL))),
    CONSTRAINT risk_events_decision_consistent CHECK (((status = ANY (ARRAY['decided'::public.risk_event_status, 'dismissed'::public.risk_event_status])) = (decision IS NOT NULL)))
);

ALTER TABLE ONLY public.risk_events FORCE ROW LEVEL SECURITY;


