    thread jsonb DEFAULT '[]'::jsonb NOT NULL,
    resolved_at timestamp with time zone,
    first_response_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    deleted_at timestamp with time zone,
    version integer DEFAULT 1 NOT NULL,
    CONSTRAINT support_tickets_resolved_consistent CHECK (((status <> ALL (ARRAY['resolved'::public.support_ticket_status, 'closed'::public.support_ticket_status])) OR (resolved_at IS NOT NULL))),
    CONSTRAINT support_tickets_thread_is_array CHECK ((jsonb_typeof(thread) = 'array'::text))
);


